using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Reflection;

namespace VSCore;

/// <summary>
/// LUT for climatic/seasonal tinting from the game assets (embedded resource
/// <c>ColorMaps.txt</c>, generated by <c>tools/gen_block_colors.py</c>).
/// </summary>
public static class ColorMaps
{
    private static readonly object _lock = new();
    private static Dictionary<string, MapTint.Lut>? _maps;

    internal static Dictionary<string, MapTint.Lut> All
    {
        get
        {
            if (_maps is not null) return _maps;
            lock (_lock)
            {
                _maps ??= Load();
                return _maps;
            }
        }
    }

    public static int Count => All.Count;

    private static Dictionary<string, MapTint.Lut> Load()
    {
        var maps = new Dictionary<string, MapTint.Lut>(StringComparer.Ordinal);
        var asm = typeof(ColorMaps).GetTypeInfo().Assembly;
        string? name = null;
        foreach (var n in asm.GetManifestResourceNames())
            if (n.EndsWith("ColorMaps.txt", StringComparison.Ordinal)) { name = n; break; }
        if (name is null) return maps;
        using var s = asm.GetManifestResourceStream(name);
        if (s is null) return maps;
        using var r = new StreamReader(s);
        string? line;
        while ((line = r.ReadLine()) is not null)
        {
            if (line.Length == 0 || line[0] == '#') continue;
            int eq = line.IndexOf('=');
            if (eq <= 0) continue;
            var dims = line[(eq + 1)..].Split('x');
            if (dims.Length != 2
                || !int.TryParse(dims[0], NumberStyles.Integer, CultureInfo.InvariantCulture, out int w)
                || !int.TryParse(dims[1], NumberStyles.Integer, CultureInfo.InvariantCulture, out int h)
                || w <= 0 || h <= 0)
                continue;
            var rgb = new byte[w * h * 3];
            for (int y = 0; y < h; y++)
            {
                var row = r.ReadLine();
                if (row is null) return maps;                  // truncated resource — do not crash
                var cells = row.Split(',');
                if (cells.Length < w) return maps;
                for (int x = 0; x < w; x++)
                {
                    if (cells[x].Length != 6 ||
                        !int.TryParse(cells[x], NumberStyles.HexNumber, CultureInfo.InvariantCulture, out int v))
                        continue;
                    int p = (y * w + x) * 3;
                    rgb[p] = (byte)(v >> 16);
                    rgb[p + 1] = (byte)(v >> 8);
                    rgb[p + 2] = (byte)v;
                }
            }
            maps[line[..eq]] = new MapTint.Lut(w, h, rgb);
        }
        return maps;
    }
}

/// <summary>
/// Tints a block colour the way the in-game map does (Block.GetColor ->
/// ApplyColorMapOnRgba): a climatic LUT by temperature/rainfall, a seasonal LUT by
/// calendar and position, then multiplication of the texture colour.
///
/// The save has no climate map (mapregion is empty and the climate is computed from worldgen noise),
/// so temperature/rainfall are constants of a temperate climate. The season, however, is real:
/// <see cref="For"/> takes YearRel from the save calendar, and that is what drives the main shift
/// (grass is olive in spring, greener in summer, brown in winter).
/// </summary>
public static class MapTint
{
    internal readonly record struct Lut(int W, int H, byte[] Rgb);

    /// <summary>Climatic units 0..255 (climate map: temperature/rainfall). The values were matched
    /// against the in-game map of a temperate world (Vintage Story 1.22): grass/water/foliage agree with the map
    /// within ~4/255. The save has no climate map, so this is a constant per world; the season
    /// (the main colour shift) comes from the calendar and is real.</summary>
    public const int DefaultTemperature = 90;
    public const int DefaultRainfall = 165;

    public static (byte R, byte G, byte B) For(string? climateMap, string? seasonMap,
        int x, int y, int z, double yearRel, int seaLevel)
    {
        if (climateMap is null && seasonMap is null) return (255, 255, 255);

        (byte, byte, byte)? climate = null;
        (byte, byte, byte)? season = null;
        var maps = ColorMaps.All;
        if (climateMap is not null && maps.TryGetValue(climateMap, out var c))
        {
            int temp = Climate.GetAdjustedTemperature(DefaultTemperature, y - seaLevel);
            int rain = Climate.GetRainFall(DefaultRainfall, y, seaLevel);
            climate = SampleClimate(c, temp, rain);
        }
        if (seasonMap is not null && maps.TryGetValue(seasonMap, out var s))
        {
            double rel = Murmur3Mod(x, y, z, 100) / 100.0;
            season = SampleSeason(s, yearRel, rel);
        }

        if (climate is null && season is null) return (255, 255, 255);
        var n = climate ?? season!.Value;
        if (climate is not null && season is not null)
        {
            float w = SeasonOverlayWeight(TemperatureFor(y, seaLevel));
            n = ((byte)(n.Item1 * (1 - w) + season.Value.Item1 * w),
                 (byte)(n.Item2 * (1 - w) + season.Value.Item2 * w),
                 (byte)(n.Item3 * (1 - w) + season.Value.Item3 * w));
        }
        return n;
    }

    /// <summary>Multiplies a colour by the tint, rounding down, like ColorMultiplyEach in the game.</summary>
    public static (byte R, byte G, byte B) Apply((byte R, byte G, byte B) color, (byte R, byte G, byte B) tint)
        => ((byte)(color.R * tint.R / 255), (byte)(color.G * tint.G / 255), (byte)(color.B * tint.B / 255));

    /// <summary>Weight of the seasonal LUT on top of the climatic one — exactly the formula of
    /// ApplyColorMapOnRgba: the colder, the stronger the seasonal hue.</summary>
    internal static float SeasonOverlayWeight(int temp)
    {
        float w = 0.5f - MathF.Cos(temp / 42f) / 2.3f
                  + Math.Max(0, 128 - temp) / 512f
                  - Math.Max(0, temp - 130) / 200f;
        return Math.Clamp(w, 0f, 1f);
    }

    /// <summary>Climate map temperature adjusted for altitude (Climate.GetAdjustedTemperature).</summary>
    internal static int TemperatureFor(int y, int seaLevel)
        => Math.Clamp((int)(DefaultTemperature - (y - seaLevel) / 1.5f), 0, 255);

    private static (byte, byte, byte) SampleClimate(Lut lut, int temp, int rain)
    {
        int ix = Math.Clamp((int)(temp / 255f * lut.W), 0, lut.W - 1);
        int iy = Math.Clamp((int)(rain / 255f * lut.H), 0, lut.H - 1);
        int p = (iy * lut.W + ix) * 3;
        return (lut.Rgb[p], lut.Rgb[p + 1], lut.Rgb[p + 2]);
    }

    private static (byte, byte, byte) SampleSeason(Lut lut, double yearRel, double seasonYPixelRel)
    {
        double rel = yearRel % 1.0;
        if (rel < 0) rel += 1;
        int ix = Math.Clamp((int)(rel * lut.W), 0, lut.W - 1);
        int iy = Math.Clamp((int)(seasonYPixelRel * lut.H), 0, lut.H - 1);
        int p = (iy * lut.W + ix) * 3;
        return (lut.Rgb[p], lut.Rgb[p + 1], lut.Rgb[p + 2]);
    }

    // ===================== game hash (GameMath.MurmurHash3) =====================
    // Needed so that the seasonal hue and the texel choice match the game at a given position.

    public static int Murmur3Mod(int x, int y, int z, int mod)
    {
        int k = Murmur3(x, y, z) % mod;
        return k < 0 ? k + mod : k;
    }

    public static int Murmur3(int x, int y, int z)
    {
        unchecked
        {
            uint h = 0x90u;
            h ^= Rotl32((uint)(x * -862048943), 15) * 461845907u;
            h = Rotl32(h, 13) * 5u + 0xE6546B64u;      // -430675100 as uint
            h ^= Rotl32((uint)(y * -862048943), 15) * 461845907u;
            h = Rotl32(h, 13) * 5u + 0xE6546B64u;
            h ^= Rotl32((uint)(z * -862048943), 15) * 461845907u;
            h = Rotl32(h, 13) * 5u + 0xE6546B64u;
            h ^= 3u;
            h = (h ^ (h >> 16)) * 2246822507u;
            h = (h ^ (h >> 13)) * 3266489909u;
            h ^= h >> 16;
            return (int)h;
        }
    }

    private static uint Rotl32(uint v, int r) => (v << r) | (v >> (32 - r));
}

/// <summary>Copy of the game API's Climate for the two functions the tint depends on.</summary>
internal static class Climate
{
    public static int GetAdjustedTemperature(int unscaledTemp, int distToSealevel)
        => (int)Math.Clamp(unscaledTemp - distToSealevel / 1.5f, 0f, 255f);

    public static int GetRainFall(int rainfall, int y, int seaLevel)
        => Math.Clamp(rainfall + (y - seaLevel) / 2
                      + 5 * Math.Clamp(8 + seaLevel - y, 0, 8), 0, 255);
}
